d":"{[0,220),[329,334),[455,460),[581,586)}"},{"id":"h3-statistics-3.2","title":"통계적 검정","grade":"고3","parent":"h3|실용 통계|자료의 분석","concept":"statistics-3.2","ordinal":586,"allowed":"{[0,220),[329,335),[455,461),[581,587)}"},{"id":"h3-statistics-4.1","title":"통계적 탐구 활동","grade":"고3","parent":"h3|실용 통계|통계적 탐구","concept":"statistics-4.1","ordinal":587,"allowed":"{[0,220),[329,336),[455,462),[581,588)}"},{"id":"h3-research-1.1","title":"수학과제 탐구의 의미와 필요성","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 이해","concept":"research-1.1","ordinal":588,"allowed":"{[0,220),[336,337),[462,463),[588,589)}"},{"id":"h3-research-1.2","title":"연구 윤리","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 이해","concept":"research-1.2","ordinal":589,"allowed":"{[0,220),[336,338),[462,464),[588,590)}"},{"id":"h3-research-2.1","title":"문헌 연구","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 방법과 절차","concept":"research-2.1","ordinal":590,"allowed":"{[0,220),[336,339),[462,465),[588,591)}"},{"id":"h3-research-2.2","title":"사례 조사","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 방법과 절차","concept":"research-2.2","ordinal":591,"allowed":"{[0,220),[336,340),[462,466),[588,592)}"},{"id":"h3-research-2.3","title":"수학 실험","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 방법과 절차","concept":"research-2.3","ordinal":592,"allowed":"{[0,220),[336,341),[462,467),[588,593)}"},{"id":"h3-research-2.4","title":"개발 연구","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 방법과 절차","concept":"research-2.4","ordinal":593,"allowed":"{[0,220),[336,342),[462,468),[588,594)}"},{"id":"h3-research-3.1","title":"주제 선정 및 계획 수립","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 실행 및 평가","concept":"research-3.1","ordinal":594,"allowed":"{[0,220),[336,343),[462,469),[588,595)}"},{"id":"h3-research-3.2","title":"탐구 수행","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 실행 및 평가","concept":"research-3.2","ordinal":595,"allowed":"{[0,220),[336,344),[462,470),[588,596)}"},{"id":"h3-research-3.3","title":"탐구 결과 정리 및 발표","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 실행 및 평가","concept":"research-3.3","ordinal":596,"allowed":"{[0,220),[336,345),[462,471),[588,597)}"},{"id":"h3-research-3.4","title":"반성 및 평가","grade":"고3","parent":"h3|수학과제 탐구|과제 탐구의 실행 및 평가","concept":"research-3.4","ordinal":597,"allowed":"{[0,220),[336,346),[462,472),[588,598)}"}]$taxonomy$::jsonb) as x(id text,title text,grade text,parent text,concept text,ordinal integer,allowed int4multirange);

create function bank_query.unit_id(m jsonb,f jsonb) returns text language sql stable set search_path='' as $$
 with primary_unit as (select coalesce(f->'primaryUnit',m#>'{classification,confirmed,primaryUnit}',m#>'{classification,primaryUnit}',m#>'{classification,suggested,primaryUnit}') v),
 found as (select u.id from bank_query.units u,primary_unit p where u.id=coalesce(p.v->>'id',p.v#>>'{}') or (u.title=coalesce(p.v->>'name',p.v#>>'{}') and (coalesce(m#>>'{source,grade}','')='' or u.grade=m#>>'{source,grade}')))
 select case when count(*)=1 then min(id) end from found;
$$;
create function bank_query.types(m jsonb,f jsonb) returns jsonb language sql immutable set search_path='' as $$
 select case when jsonb_array_length(coalesce(f->'types','[]'))>0 then f->'types'
 when coalesce(f->>'type',f->>'typeId','')<>'' then jsonb_build_array(jsonb_build_object('id',coalesce(f->>'typeId',f->>'type'),'name',coalesce(f->>'type',f->>'typeId')))
 when jsonb_array_length(coalesce(m#>'{classification,confirmed,types}','[]'))>0 then m#>'{classification,confirmed,types}'
 when coalesce(m#>>'{classification,confirmed,type}','')<>'' then jsonb_build_array(jsonb_build_object('id',m#>>'{classification,confirmed,type}','name',m#>>'{classification,confirmed,type}'))
 else coalesce(m#>'{classification,types}','[]') end;
$$;
create function bank_query.type_key(m jsonb,f jsonb) returns text language sql immutable set search_path='' as $$
 with t as(select bank_query.types(m,f)->0 v),recommended as(select x from jsonb_array_elements(coalesce(m#>'{classification,types}','[]')) x,t where x->>'id'=t.v->>'id' limit 1)
 select nullif(coalesce(t.v->>'repeatKey',(select x->>'repeatKey' from recommended),t.v->>'id',t.v->>'name',t.v#>>'{}'),'') from t;
$$;
create function bank_query.safe_units(ids jsonb,allowed jsonb,forbidden jsonb) returns boolean language sql stable set search_path='' as $$
 select not exists(select 1 from jsonb_array_elements_text(coalesce(ids,'[]')) v where not allowed ? v or forbidden ? v
 or exists(select 1 from bank_query.units a join bank_query.units b on b.concept=a.concept where a.id=v and a.concept is not null and forbidden ? b.id));
$$;
create function bank_query.scope_fit(m jsonb,f jsonb,rules jsonb) returns boolean language plpgsql stable set search_path='' as $$
declare selected jsonb:=coalesce(rules->'units','[]'); forbidden jsonb:=coalesce(rules->'forbidden','[]'); allowed jsonb; unit text; c jsonb:=coalesce(m->'classification','{}'); evidence jsonb; solutions jsonb; conditions jsonb;begin
 unit:=bank_query.unit_id(m,f);
 if jsonb_array_length(selected)=0 then selected:=case when unit is null then '[]'::jsonb else jsonb_build_array(unit) end;end if;
 if jsonb_array_length(selected)=0 then return false;end if;
 if m#>>'{analysis,status}'='stale' and c->'confirmed' is null and coalesce(f->'scopeEvidence',c->'scopeEvidence') is null then return false;end if;
 select coalesce(jsonb_agg(distinct a.id),'[]') into allowed from bank_query.units u join bank_query.units a on a.ordinal <@ u.allowed where selected ? u.id;
 evidence:=coalesce(f->'scopeEvidence',c->'scopeEvidence',c->'confirmed',c);
 solutions:=coalesce(evidence->'solutions',c#>'{suggested,solutions}','[]');conditions:=coalesce(evidence->'conditionUnitIds',c#>'{suggested,conditionUnitIds}','[]');
 if unit is not null and not selected ? unit then return false;end if;
 if unit is null and not exists(select 1 from jsonb_array_elements(solutions) sol cross join lateral jsonb_array_elements_text(coalesce(sol->'unitIds','[]')) u where selected ? u) then return false;end if;
 if unit is not null and not bank_query.safe_units(jsonb_build_array(unit),allowed,forbidden) then return false;end if;
 if not bank_query.safe_units(conditions,allowed,forbidden) then return false;end if;
 if exists(select 1 from jsonb_array_elements(solutions) sol where jsonb_array_length(coalesce(sol->'unitIds','[]'))>0)
 and not exists(select 1 from jsonb_array_elements(solutions) sol where jsonb_array_length(coalesce(sol->'unitIds','[]'))>0 and bank_query.safe_units(sol->'unitIds',allowed,forbidden) and bank_query.safe_units(sol->'dependencyUnitIds',allowed,forbidden)) then return false;end if;
 return true;
end $$;
create function bank_query.latest(s uuid) returns setof public.bank_catalog language sql stable set search_path='' as $$
 select distinct on(c.question_id) c.* from public.bank_catalog c join public.bank_revisions r on r.id=c.revision_id join public.bank_questions q on q.id=c.question_id
 where c.space_id=s and public.bank_member(s) and r.committed and not q.archived and public.bank_read_revision(c.revision_id)
 order by c.question_id,c.created_at desc,c.revision_id desc;
$$;
create function bank_query.compact(c public.bank_catalog) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('question_id',c.question_id,'revision_id',c.revision_id,'space_id',c.space_id,'created_at',c.created_at,
 'visibility',(select visibility from public.bank_revisions where id=c.revision_id),
 'metadata',jsonb_build_object('source',c.metadata->'source','content',jsonb_build_object('responseType',c.metadata#>>'{content,responseType}'),
 'classification',jsonb_build_object('primaryUnit',jsonb_build_object('id',u.id,'name',u.title),'types',bank_query.types(c.metadata,c.confirmed)),
 'difficulty','{}'::jsonb),
 'summaryDifficulty',bank_summary.row_difficulty(c.revision_id,c.metadata,c.confirmed),'confirmed',jsonb_build_object('originalPoints',c.confirmed->'originalPoints'),
 'content',jsonb_build_object('body',left(c.content->>'body',160))) from (select 1) one left join bank_query.units u on u.id=bank_query.unit_id(c.metadata,c.confirmed);
$$;
create function public.bank_replacement_page(s uuid,current_revision uuid,rules jsonb,selected uuid[],page integer default 0,expanded boolean default false,expected_version text default null,candidate uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare target public.bank_catalog;tu text;tt text;tp text;result jsonb;begin
 if not public.bank_member(s) then raise insufficient_privilege;end if;
 if page<0 or page>100000 or jsonb_typeof(rules)<>'object' or coalesce(array_length(selected,1),0)>1000 then raise exception '조회 조건을 확인하세요.';end if;
 select * into target from public.bank_catalog where space_id=s and revision_id=current_revision and public.bank_read_revision(revision_id);
 if not found then raise insufficient_privilege;end if;
 if exists(select 1 from public.bank_question_sets qs where qs.space_id=s and qs.source_document=target.metadata#>>'{source,documentId}' and (target.metadata#>>'{source,originalNumber}')=any(qs.original_numbers)) then raise exception '세트 문항은 개별 교체할 수 없습니다.';end if;
 tu:=bank_query.unit_id(target.metadata,target.confirmed);tt:=bank_query.type_key(target.metadata,target.confirmed);select parent into tp from bank_query.units where id=tu;
 return (with candidates as materialized(
 select c,bank_query.unit_id(c.metadata,c.confirmed) unit,bank_query.type_key(c.metadata,c.confirmed) typ,
 (jsonb_array_length(coalesce(rules->'schools','[]'))=0 or coalesce(rules->'schools','[]') ? coalesce(c.metadata#>>'{source,school}','')) local_school
 from bank_query.latest(s) c where c.question_id<>target.question_id and not(c.question_id=any(coalesce(selected,'{}'::uuid[])))
 and not coalesce(rules->'excludeIds','[]') ? c.question_id::text
 and bank_query.scope_fit(c.metadata,c.confirmed,rules)
 and (coalesce(rules->>'unit','')='' or exists(select 1 from bank_query.units u where u.id=bank_query.unit_id(c.metadata,c.confirmed) and (u.id=rules->>'unit' or u.title=rules->>'unit')))
 and public.bank_type_matches(c.metadata,c.confirmed,rules->>'type')
 and (coalesce(rules->>'originalsOnly','false')<>'true' or (c.metadata#>>'{source,kind}'='학교기출' and coalesce(c.metadata#>>'{relations,originalQuestionId}','')=''))
 and not exists(select 1 from public.bank_question_sets qs where qs.space_id=s and qs.source_document=c.metadata#>>'{source,documentId}' and (c.metadata#>>'{source,originalNumber}')=any(qs.original_numbers))
 and (select count(*) from public.bank_revisions h where h.question_id=c.question_id and h.committed and public.bank_read_revision(h.id) and not exists(select 1 from public.bank_revisions child where child.parent_id=h.id and child.committed))=1
 ),ranked as materialized(select c,local_school,case when unit=tu and typ=tt then 1 when unit=tu then 2 else 3 end tier,unit=tu same_unit,coalesce(typ=tt,false) same_type
 from candidates where (local_school and (unit=tu or (tp is not null and exists(select 1 from bank_query.units where id=unit and parent=tp)))) or (not local_school and unit=tu and typ=tt)),
 counts as(select count(*) filter(where local_school) base,count(*) filter(where not local_school) extra,md5(coalesce(string_agg((c).question_id::text||':'||(c).revision_id::text||':'||md5(coalesce((c).metadata::text,'')||coalesce((c).confirmed::text,'')||coalesce((c).content::text,''))||':'||tier||':'||local_school,',' order by tier,(c).question_id),'')) version from ranked),
 shown as(select * from ranked where (local_school or expanded) and (candidate is null or (c).question_id=candidate) order by tier,(c).question_id,(c).revision_id limit case when candidate is null then 10 else 1 end offset case when candidate is null then page*10 else 0 end)
 select jsonb_build_object('baseCount',base,'extraCount',extra,'total',base+case when expanded then extra else 0 end,'version',version,'changed',expected_version is not null and expected_version<>version,
 'items',case when expected_version is not null and expected_version<>version then '[]'::jsonb else (select coalesce(jsonb_agg(bank_query.compact(c)||jsonb_build_object('tier',tier,'sameUnit',same_unit,'sameType',same_type,'sameParent',tier=3,'otherSchool',not local_school) order by tier,(c).question_id),'[]') from shown) end) from counts);
end $$;
revoke all on all functions in schema bank_query from public,anon,authenticated;
revoke all on function public.bank_replacement_page(uuid,uuid,jsonb,uuid[],integer,boolean,text,uuid) from public,anon,authenticated;
grant execute on function public.bank_replacement_page(uuid,uuid,jsonb,uuid[],integer,boolean,text,uuid) to authenticated;
commit;

